digraph DNS_Resolution {
  graph [
    rankdir=TB,
    labelloc="t",
    label="DNS Address Resolution Process\nDisclaimer: This diagram was generated with an AI model.",
    fontsize=18,
    fontname="Arial",
    nodesep=0.35,
    ranksep=0.45,
    splines=ortho
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#DCEAF7",
    color="#52789C",
    fontname="Arial",
    fontsize=11,
    width=2.8,
    height=0.65
  ];

  edge [
    color="#52789C",
    fontname="Arial",
    fontsize=10,
    arrowsize=0.7
  ];

  start [shape=oval, label="Request is made to a URI"];
  inspect [label="Read the server address\nfrom the URI"];
  is_ip [shape=diamond, style="filled", label="Is the server address\nalready an IP address?"];
  check_cache [shape=diamond, style="filled", label="Is the address and its IP\nin the computer's cache?"];
  local [label="Resolve the IP address locally\nusing the cached entry"];
  query [label="Send the text-based address\nto a DNS server"];
  response [label="DNS server returns the\ncorresponding IP address"];
  store [label="Store the address and IP\nin the computer's cache"];
  send [label="Send the message to the\nactual IP address"];
  finish [shape=oval, label="Continue communication\nwith the destination server"];

  start -> inspect -> is_ip;
  is_ip -> send [label="Yes"];
  is_ip -> check_cache [label="No"];
  check_cache -> local [label="Yes"];
  check_cache -> query [label="No"];
  query -> response -> store;
  local -> send;
  store -> send;
  send -> finish;
}

