    labelloc="t";
    color="#4F6D7A";
    fontname="Arial Bold";
    fontsize=15;
    style="rounded";
    margin=18;

    decomposition [label="Decomposition (Factoring)\nBreak a problem into manageable parts so that\nsolutions can be found for each part."];

    pattern [label="Pattern Recognition\nIdentify similarities within or between problems so that\npast solutions and knowledge can be reused."];

    algorithms [label="Algorithms\nDevelop step-by-step solutions for each part\nof the problem."];

    abstraction [label="Abstraction\nGeneralise the important details so that\na solution can be reused."];

    decomposition -> pattern -> algorithms -> abstraction;
  }
}

digraph DataCombinationProcess {
  graph [
    rankdir=TB,
    bgcolor="white",
    pad=0.25,
    nodesep=0.25,
    ranksep=0.38,
    labelloc="t",
    label="Steps in the Data Combination Process\nDisclaimer: This diagram was generated with an AI model.",
    fontsize=18,
    fontname="Arial"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fixedsize=true,
