  step1 [label="1. Create a new copy of the main data file,\nincluding today’s date in the file name."];
  step2 [label="2. Move the previous version of the main data file\nto cloud storage."];
  step3 [label="3. Save each new data file separately to local storage,\nincluding its device ID in the file name."];
  step4 [label="4. Create a new weekly data digest for importing\nthe daily digests from the different devices."];
  step5 [label="5. Import each daily digest into the weekly data file\nusing an append command."];
