digraph GapminderLifeExpectancy {
  graph [
    rankdir=TB,
    splines=ortho,
    nodesep=0.35,
    ranksep=0.45,
    bgcolor="white",
    label="Gapminder Mean Life Expectancy by Continent\nDisclaimer: This diagram was generated with an AI model.",
    labelloc="t",
    fontsize=16,
    fontname="Arial"
  ];

  node [
    style="filled",
    fillcolor="#E8F1F8",
    color="#4A6A80",
    fontname="Arial",
    fontsize=11,
    width=3.0
  ];

  edge [
    color="#4A6A80",
    fontname="Arial",
    fontsize=10,
    arrowsize=0.7
  ];

  start     [shape=ellipse, label="Start"];
  unique    [shape=box, label="Extract unique values\nfrom the continent vector"];
  initialize [shape=box, label="Initialize loop over\nunique continents"];
  more      [shape=diamond, label="Another continent\nto process?"];
  subset    [shape=box, label="Create a temporary subset\nfor the current continent"];
  mean      [shape=box, label="Calculate mean\nlife expectancy"];
  threshold [shape=diamond, label="Is the mean life\nexpectancy < 50 years?"];
  print_low [shape=box, label="Print continent and:\n'Life expectancy is\nless than 50 years'"];
  print_high [shape=box, label="Print continent and:\n'Life expectancy is\ngreater than 50 years'"];
  next      [shape=box, label="Advance to the\nnext continent"];
  finish    [shape=ellipse, label="End"];

  start -> unique -> initialize -> more;
  more -> subset [label="Yes"];
  more -> finish [label="No"];
  subset -> mean -> threshold;
  threshold -> print_low [label="Yes"];
  threshold -> print_high [label="No"];
  print_low -> next;
  print_high -> next;
  next -> more;

  { rank=same; print_low; print_high; }
}

