digraph SynchronousAlgorithm {
  graph [
    rankdir=TB,
    bgcolor="white",
    pad="0.25",
    nodesep="0.35",
    ranksep="0.45",
    splines=ortho,
    label="Synchronous execution of Algorithm A\nGenerated with an AI model.",
    labelloc=b,
    fontsize=12,
    fontname="Arial"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#DCEAF7",
    color="#4F6F8F",
    fontname="Arial",
    fontsize=11,
    width=3.8,
    height=0.65
  ];

  edge [
    color="#4F6F8F",
    fontname="Arial",
    fontsize=10,
    arrowsize=0.75
  ];

  start  [label="All computers start simultaneously\nand follow Algorithm A"];
  round  [label="Begin a synchronous communication round\n(all computers act in parallel)"];
  send   [label="1. Send a message to each port"];
  wait   [label="2. Wait while messages propagate\nalong the communication channels"];
  receive[label="3. Receive a message from each port"];
  update [label="4. Update the computer's own state"];

  start -> round -> send -> wait -> receive -> update;
  update -> round [label=" next round", constraint=false];
}

digraph NodeColoring {
  graph [
    rankdir=TB,
    bgcolor="white",
    pad=0.25,
    nodesep=0.35,
    ranksep=0.45,
    splines=ortho,
    labelloc="t",
    label="Randomized Node-Coloring Process for Each Node u\nGenerated with an AI model",
    fontsize=16,
    fontname="Helvetica"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#E8F1F8",
    color="#486581",
    fontcolor="#102A43",
    fontname="Helvetica",
    fontsize=11,
    width=2.8,
    margin="0.12,0.08"
  ];

  edge [
    color="#486581",
    fontcolor="#334E68",
    fontname="Helvetica",
    fontsize=10,
    arrowsize=0.7
  ];

  init [label="Initialize\ns(u) ← 1,  c(u) ← ⊥"];
  receive1 [label="State s(u) = 1\nReceive messages M(u)"];
  choice [shape=diamond, label="Random choice", width=2.2, height=1.0, fixedsize=true];
  passive [label="Passive\nc(u) ← ⊥"];
  active [label="Active\nF(u) ← C(u) \\ M(u)\nPick random c(u) ∈ F(u)"];
  switch0 [label="Set s(u) ← 0"];
  receive0 [label="State s(u) = 0\nReceive messages M(u)\nand verify the choice"];
  valid [shape=diamond, label="c(u) ≠ ⊥\nand\nc(u) ∉ M(u)?", width=2.2, height=1.25, fixedsize=true];
  reset [label="Passive or conflicting choice\nReset s(u) ← 1,  c(u) ← ⊥"];
  stop [label="Stopping state\nKeep c(u)\ns(u) = 1,  c(u) ≠ ⊥", penwidth=2];

  init -> receive1;
  receive1 -> choice;
  choice -> passive [label="0.5"];
  choice -> active [label="0.5"];
  passive -> switch0;
  active -> switch0;
  switch0 -> receive0;
  receive0 -> valid;
  valid -> stop [label="Yes"];
  valid -> reset [label="No"];
  reset -> receive1 [constraint=false, label="Try again"];

  { rank=same; passive; active; }
  { rank=same; stop; reset; }
}

