digraph XSS_Attack {
  graph [
    rankdir=TB,
    bgcolor="white",
    pad=0.25,
    nodesep=0.35,
    ranksep=0.45,
    splines=ortho,
    labelloc="t",
    label="Stored Cross-Site Scripting (XSS) Attack Flow\nDisclaimer: This diagram was generated with an AI model."
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#E8F1FA",
    color="#3973A5",
    fontname="Arial",
    fontsize=10,
    fixedsize=true,
    width=3.6,
    height=0.75,
    margin="0.12,0.08"
  ];

  edge [
    color="#4F5B66",
    fontname="Arial",
    fontsize=9,
    arrowsize=0.75
  ];

  attacker [label="Attacker creates a malicious\nclient-side script"];
  inject [label="Attacker submits the script through\na form or API endpoint"];
  receive [label="Web application accepts the\nmalicious input"];
  store [label="Server stores the script without\nexecuting it on the server"];
  request [label="Another user requests the\naffected content"];
  response [label="Server responds normally with content\nthat includes the stored script"];
