digraph TCP_Connection_Release {
  graph [
    rankdir=TB,
    bgcolor="white",
    pad=0.25,
    nodesep=0.35,
    ranksep=0.5,
    splines=ortho,
    label="TCP Connection Release\nAI-generated diagram; verify details against RFCs 793, 3360, and 4953.",
    labelloc="t",
    labeljust="c",
    fontsize=16,
    fontname="Arial"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#E8F1FA",
    color="#4D6A80",
    fontcolor="#1F2D38",
    fontname="Arial",
    fontsize=11,
    width=3.8,
    margin="0.18,0.12"
  ];

  edge [
    color="#4D6A80",
    penwidth=1.2,
    arrowsize=0.7,
    fontname="Arial",
    fontsize=10
  ];

  release [label="TCP connection release"];
  graceful [label="Graceful release"];
  abrupt [label="Abrupt release"];

  graceful_effect [label="Each TCP user releases its own\ndirection of data transfer"];

  abrupt_effect [label="One user closes both directions, or a TCP\nentity is forced to close the connection\n(e.g., no remote reply or insufficient resources)"];

  rst_mechanism [label="Mechanism: a single TCP segment\nwith the RST bit set"];

  rst_reasons [label="An RST segment may be sent when:\n\n1. A non-SYN segment is received for a\nnon-existing connection (RFC 793)\n\n2. Some implementations receive an invalid\nheader on an existing connection (RFC 3360);\nthis closes the connection and has enabled\nsecurity attacks (RFC 4953)\n\n3. An implementation must close an existing\nconnection because resources are insufficient\nor the remote host seems unreachable;\nmeasurements found this usage widespread"];

  release -> graceful;
  release -> abrupt;
  graceful -> graceful_effect;
  abrupt -> abrupt_effect;
  abrupt_effect -> rst_mechanism;
  rst_mechanism -> rst_reasons;

  { rank=same; graceful; abrupt; }
  { rank=same; graceful_effect; abrupt_effect; }
}

