digraph ColorSelectionAlgorithm {
    graph [
        rankdir=TB,
        bgcolor="white",
        labelloc=t,
        label="Randomized color-selection algorithm\nGenerated with an AI model.",
        fontname="Helvetica",
        fontsize=16,
        nodesep=0.45,
        ranksep=0.65,
        splines=polyline
    ];

    node [
        fontname="Helvetica",
        fontsize=11,
        style="rounded,filled",
        color="#4A5568",
        penwidth=1.2,
        fillcolor="#EAF2F8"
    ];

    edge [
        fontname="Helvetica",
        fontsize=10,
        color="#4A5568",
        arrowsize=0.7
    ];

    start [
        shape=oval,
        fillcolor="#D5F5E3",
        label="For each node u"
    ];

    init [
        shape=box,
        label="Initialize\ns(u) ← 1\nc(u) ← ⊥"
    ];

    phase1 [
        shape=box,
        label="s(u) = 1\nReceive M(u)"
    ];

    choose [
        shape=diamond,
        fillcolor="#FCF3CF",
        label="Choose behavior\nwith probability 0.5"
    ];

    passive [
        shape=box,
        label="Passive\nc(u) ← ⊥"
    ];

    active [
        shape=box,
        label="Active\nChoose random c(u) ∈ F(u)\nF(u) = C(u) − M(u)"
    ];

    set0 [
        shape=box,
        label="Set s(u) ← 0"
    ];

    phase0 [
        shape=box,
        label="s(u) = 0\nReceive M(u)\nVerify c(u)"
    ];

    conflict [
        shape=diamond,
        fillcolor="#FCF3CF",
        label="Conflict?\nc(u) ∈ M(u)"
    ];

    reset [
        shape=box,
        label="Reset\ns(u) ← 1\nc(u) ← ⊥"
    ];

    stop [
        shape=oval,
        fillcolor="#D5F5E3",
        label="Stopping state\ns(u) = 1\nc(u) ≠ ⊥\nKeep c(u)"
    ];

    start -> init;
    init -> phase1;
    phase1 -> choose;

    choose -> passive [label="passive"];
    choose -> active [label="active"];

    { rank=same; passive; active; }
    passive -> set0;
    active -> set0;

    set0 -> phase0;
    phase0 -> conflict;

    conflict -> reset [label="yes"];
    conflict -> stop [label="no"];

    reset:w -> phase1:w [
        label="next round",
        constraint=false
    ];
}

