    ];

    release [label="TCP connection release"];
    graceful [label="Graceful connection release"];
    graceful_detail [label="Each TCP user releases its own\ndirection of data transfer"];

    abrupt [label="Abrupt connection release"];
    abrupt_scope [label="Either one user closes both directions,\nor a TCP entity is forced to close\n(e.g., no reply or lack of resources)"];
    rst [label="Single TCP segment\nwith the RST bit set"];

    reasons [label="RST segment may be sent when:\n\n1. A non-SYN segment arrives for a\n   non-existing TCP connection (RFC 793)\n\n2. An existing connection receives an\n   invalid header; some implementations\n   respond with RST (RFC 3360), which has\n   caused security attacks (RFC 4953)\n\n3. An implementation must close an existing\n   connection, e.g. due to insufficient\n   resources or an unreachable remote host;\n   this usage has been measured as widespread"];

    closed [label="Corresponding TCP connection is closed", fillcolor="#D5F5E3"];

    release -> graceful;
    release -> abrupt;

    graceful -> graceful_detail;
    abrupt -> abrupt_scope;
    abrupt_scope -> rst;
    rst -> reasons;
    reasons -> closed;
}

