digraph Algorithm {
  graph [label="Randomized Color Selection Algorithm\n(Generated with an AI model)", labelloc=t, labeljust=c, rankdir=TB, splines=ortho, nodesep=0.35, ranksep=0.45];
  node [shape=box, style="rounded,filled", fillcolor=lightblue, color=steelblue, fontname="Arial", fontsize=10, margin="0.12,0.08"];
