  init [label="Initialize for each node u:\ns(u) ← 1\nc(u) ← ⊥", fillcolor=lightgreen];
  active [label="State s(u) = 1\nReceive message set M(u)\nChoose with probability 0.5:", fillcolor=lightyellow];
  passive [label="Passive choice\nc(u) ← ⊥", fillcolor=mistyrose];
  choose [label="Active choice\nPick random c(u) ∈ F(u)\nF(u) = C(u) \\ M(u)", fillcolor=lightyellow];
  setzero [label="Set s(u) ← 0", fillcolor=lightblue];
  verify [label="State s(u) = 0\nReceive message set M(u)\nVerify current color", fillcolor=lightyellow];
  conflict [label="Conflict?\nc(u) ∈ M(u)", shape=diamond, fillcolor=orange];
  retry [label="Reset and retry\ns(u) ← 1\nc(u) ← ⊥", fillcolor=mistyrose];
  success [label="No conflict\nKeep c(u)\nSwitch to stopping state:\ns(u) = 1, c(u) ≠ ⊥", fillcolor=lightgreen];

  init -> active;
  active -> passive [label="0.5"];
  active -> choose [label="0.5"];
  passive -> setzero;
  choose -> setzero;
  setzero -> verify;
  verify -> conflict;
  conflict -> retry [label="yes"];
  conflict -> success [label="no"];
  retry -> active [label="next round"];
}

