digraph TCP_Connection_Release {
  graph [label="TCP Connection Release\nGenerated with an AI model", labelloc="t", labeljust="c", rankdir=TB, splines=ortho, nodesep=0.35, ranksep=0.55, bgcolor="white"];
  node [shape=box, style="rounded,filled", fillcolor="lightblue", color="steelblue4", fontname="Arial", fontsize=10, margin="0.12,0.08"];
