  tcp -> abrupt;

  graceful_user1 [label="Each TCP user releases\nits own data direction"];
  graceful_user2 [label="Directions can be released\nindependently"];
  graceful -> graceful_user1;
  graceful -> graceful_user2;

  abrupt_action [label="Either user closes\nboth data directions"];
