  abrupt -> abrupt_action;
  abrupt -> abrupt_forced;

  rst [label="Single TCP segment\nwith RST bit set", fillcolor="lightyellow", color="darkgoldenrod4", penwidth=1.5];
  abrupt -> rst;

  reasons [label="Reasons for sending RST", fillcolor="lightsteelblue"];
  rst -> reasons;

  nonexistent [label="Non-SYN segment received\nfor a nonexistent TCP connection\n(RFC 793)"];
  invalid [label="Segment received on an existing\nconnection with an invalid header\n(some implementations; RFC 3360)\nCan cause security attacks (RFC 4953)"];
  resources [label="Existing connection must be closed\n(e.g. insufficient resources or\nremote host considered unreachable)\nWidespread in measurements"];
  reasons -> nonexistent;
  reasons -> invalid;
  reasons -> resources;

  consequence [label="RST causes the corresponding\nconnection to close", fillcolor="mistyrose", color="firebrick4"];
  invalid -> consequence;
  resources -> consequence;
}

