digraph ColoringAlgorithm {
  graph [
    rankdir=TB,
    bgcolor="white",
    pad="0.3",
    nodesep="0.45",
    ranksep="0.6",
    labelloc="t",
    label="Node Coloring State Machine\nDisclaimer: This diagram was generated with an AI model.",
    fontsize=18,
    fontname="Arial"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#EAF2F8",
    color="#2E86C1",
    penwidth=1.4,
    fontname="Arial",
    fontsize=11,
    margin="0.16,0.10"
  ];
  edge [
    color="#566573",
    penwidth=1.2,
    arrowsize=0.75,
    fontname="Arial",
    fontsize=10
  ];

  init [label="Initialize node u\ns(u) ← 1\nc(u) ← ⊥"];

  state1 [label="State: s(u) = 1 and c(u) = ⊥\nReceive messages M(u)\nCompute free colors: F(u) = C(u) − M(u)"];

  choose [
    shape=diamond,
    style="filled",
    fillcolor="#FCF3CF",
    color="#D4AC0D",
    label="Random choice\n(probability 0.5 each)"
  ];

  passive [label="Passive\nc(u) ← ⊥"];
  active [label="Active\nChoose random c(u) ∈ F(u)"];

  state0 [label="State: s(u) = 0\nReceive messages M(u)\nVerify current choice c(u)"];

  conflict [
    shape=diamond,
    style="filled",
    fillcolor="#FCF3CF",
    color="#D4AC0D",
    label="Does c(u) ∈ M(u)?\n(conflict with a neighbor)"
  ];

  reset [label="Reset\ns(u) ← 1\nc(u) ← ⊥"];
  stop [label="Stopping state\ns(u) = 1 and c(u) ≠ ⊥\nKeep c(u)", fillcolor="#E8F8F5", color="#17A589"];

  init -> state1;
  state1 -> choose;
  choose -> passive [label="passive"];
  choose -> active [label="active"];
  passive -> state0 [label="s(u) ← 0"];
  active -> state0 [label="s(u) ← 0"];
  state0 -> conflict;
  conflict -> reset [label="yes"];
  conflict -> stop [label="no"];
  reset -> state1;

  { rank=same; passive; active; }
}

