  ];

  las_vegas [
    label="Las Vegas algorithm\n• Stops within T(n) with probability p\n• Whenever it stops, its output\n  for problem Π is always correct",
    fillcolor="#FFF1DF"
  ];

  unmet [
    label="Did the algorithm fail\nto meet its guarantee?",
    shape=diamond,
    width=2.5,
    height=1.1,
    fillcolor="#F8E4B7",
    color="#A96812"
  ];

  mc_failure [
    label="Monte Carlo:\nThe output was not correct",
    fillcolor="#E8F4EC"
  ];

  lv_failure [
    label="Las Vegas:\nThe algorithm did not stop\nwithin T(n)",
    fillcolor="#FFF1DF"
  ];

  intro -> monte_carlo;
  intro -> las_vegas;

  { rank=same; monte_carlo; las_vegas; }
  monte_carlo -> las_vegas [style=invis, weight=8];

  monte_carlo -> unmet;
  las_vegas -> unmet;

  unmet -> mc_failure [xlabel="Monte Carlo"];
  unmet -> lv_failure [xlabel="Las Vegas"];

  { rank=same; mc_failure; lv_failure; }
  mc_failure -> lv_failure [style=invis, weight=8];
}

