digraph NodeColoringAlgorithm {
  graph [
    rankdir=TB,
    bgcolor="white",
    pad="0.35",
    nodesep="0.45",
    ranksep="0.55",
    labelloc="b",
    label="Node state algorithm\nDisclaimer: This diagram was generated with an AI model.",
    fontsize=12,
    fontname="Arial"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#EAF2F8",
    color="#2874A6",
    fontcolor="#1B2631",
    fontname="Arial",
    fontsize=10,
    margin="0.16,0.10"
  ];

  edge [
    color="#566573",
    fontname="Arial",
    fontsize=9,
    arrowsize=0.7
  ];

  start [label="Initialize node u\ns(u) ← 1\nc(u) ← ⊥", fillcolor="#D5F5E3", color="#1E8449"];
  state1 [label="State s(u) = 1\nReceive messages M(u)\nCompute F(u) = C(u) \\ M(u)"];
  choice [shape=diamond, label="Random decision\n(probability 0.5 each)", fillcolor="#FCF3CF", color="#B7950B"];
  passive [label="Passive\nc(u) ← ⊥"];
  active [label="Active\nChoose random c(u) ∈ F(u)"];
  set0 [label="Set s(u) ← 0"];
  verify [label="State s(u) = 0\nReceive messages M(u)\nVerify current choice"];
  conflict [shape=diamond, label="Does c(u) ∈ M(u)?", fillcolor="#FCF3CF", color="#B7950B"];
  reset [label="Conflict found\ns(u) ← 1\nc(u) ← ⊥", fillcolor="#FADBD8", color="#C0392B"];
  stop [label="Stop: successful color\nKeep c(u)\ns(u) = 1 and c(u) ≠ ⊥", fillcolor="#D5F5E3", color="#1E8449"];

  start -> state1;
  state1 -> choice;
  choice -> passive [label="passive"];
  choice -> active [label="active"];
  passive -> set0;
  active -> set0;
  set0 -> verify;
  verify -> conflict;
  conflict -> reset [label="yes"];
  conflict -> stop [label="no"];
  reset -> state1 [label="retry"];

  { rank=same; passive; active; }
  { rank=same; reset; stop; }
}

