  newstate [label="Move forward\nto new state\n(current state + 1–6)"];
  check [label="New state type?", shape=diamond, fillcolor="#FDEDEC", color="#CB4335", margin="0.10,0.06"];
  ordinary [label="Ordinary state\nRemain there"];
  snake [label="Snake head\nMove backward to tail", fillcolor="#FADBD8", color="#C0392B"];
  ladder [label="Ladder base\nClimb to ladder top", fillcolor="#D5F5E3", color="#239B56"];
  continue [label="Continue from\nresulting state"];
  terminal [label="Terminal state\n100", fillcolor="#D5F5E3", color="#239B56", penwidth=2];

  start -> roll;
  roll -> newstate [label="1, 2, 3, 4, 5, or 6"];
  newstate -> check;
  check -> ordinary [label="ordinary"];
  check -> snake [label="snake head"];
  check -> ladder [label="ladder base"];
  ordinary -> continue;
  snake -> continue;
  ladder -> continue;
  continue -> roll [label="if state < 100", constraint=false, minlen=2];
  continue -> terminal [label="when state = 100"];
}

