digraph TCPConnectionRelease {
  graph [
    label="TCP Connection Release\nDisclaimer: This diagram was generated with an AI model.",
    labelloc=t,
    fontsize=20,
    fontname="Arial",
    rankdir=TB,
    nodesep=0.45,
    ranksep=0.6,
    bgcolor="white"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fillcolor="#EAF2F8",
    color="#2874A6",
    fontname="Arial",
    fontsize=12,
    margin="0.18,0.10"
  ];

  edge [
    color="#566573",
    penwidth=1.3,
    arrowsize=0.8,
    fontname="Arial",
    fontsize=10
  ];

  release [label="TCP connection release"];

  graceful [label="Graceful release\nEach TCP user releases its own\ndirection of data transfer", fillcolor="#E8F8F5", color="#148F77"];
  abrupt [label="Abrupt release\nOne user closes both directions, or\na TCP entity is forced to close", fillcolor="#FDEDEC", color="#C0392B"];

  rst [label="Mechanism: a single TCP segment\nwith the RST bit set", fillcolor="#FADBD8", color="#C0392B"];

  r1 [label="Non-SYN segment received for\na non-existing TCP connection\n(RFC 793)"];
  r2 [label="Segment received on an existing\nconnection with an invalid header\n(Some implementations; RFC 3360)"];
  r3 [label="Implementation needs to close an\nexisting connection\n(e.g., insufficient resources or\nremote host considered unreachable)"];

  close [label="Corresponding TCP connection closes", fillcolor="#FDEDEC", color="#C0392B"];
  risk [label="May cause security attacks\n(RFC 4953)", fillcolor="#FCF3CF", color="#B7950B"];
  widespread [label="This use of TCP RST has been\nobserved as widespread", fillcolor="#FCF3CF", color="#B7950B"];

  release -> graceful;
  release -> abrupt;
  abrupt -> rst;
  rst -> r1;
  rst -> r2;
  rst -> r3;
  r2 -> close;
  r2 -> risk;
  r3 -> widespread;

  { rank=same; graceful; abrupt; }
  { rank=same; r1; r2; r3; }
}

