digraph {
    compound=true
    graph [fontname=Lato rankdir=TB splines=ortho]
    node [fontname=Lato style="filled,rounded" margin=0.2 penwidth=0 colorscheme=blues9]
    edge [fontname=Lato color="#2B303A"]

    A [label="Distinction between 'Monte Carlo' and 'Las Vegas' type algorithms" shape="plaintext" fillcolor=3 width=2]
    B [label="Monte Carlo" shape="plaintext" fillcolor=2 width=1.5 height=1]
    C [label="Always stops in time T(n)" shape="plaintext" fillcolor=2 width=1.2]
    D [label="Output is correct with probability p" shape="plaintext" fillcolor=2 width=1.2]
    E [label="Las Vegas" shape="plaintext" fillcolor=4 width=1.5 height=1]
    F [label="Stops in time T(n) with probability p" shape="plaintext" fillcolor=4 width=1.2]
    G [label="When it stops" shape="plaintext" fillcolor=4 width=1]
    H [label="Output is always correct" shape="plaintext" fillcolor=4 width=1.2]
    I [label="If algorithm does not meet its guarantee" shape="plaintext" fillcolor=6 width=2]
    J [label="Las Vegas: did not stop in time T(n)" shape="plaintext" fillcolor=6 width=1.5]
    K [label="Monte Carlo: did not produce correct output" shape="plaintext" fillcolor=6 width=1.5]

    // Grouping for Monte Carlo
    subgraph cluster_monte {
        style="rounded" label="Monte Carlo" fontsize=15 color=lightgrey
        B -> C [dir=none]
        B -> D [dir=none]
    }
    // Grouping for Las Vegas
    subgraph cluster_lasvegas {
        style="rounded" label="Las Vegas" fontsize=15 color=lightgrey
        E -> F [dir=none]
        F -> G [dir=none]
        G -> H [dir=none]
    }

    // Main contrast between types
    A -> B [dir=none]
    A -> E [dir=none]
    // Consequence/condition edges
    I -> J [dir=none]
    I -> K [dir=none]

