digraph Memoization {
  rankdir=TB;
  node [shape=rectangle, style=filled, fillcolor=lightblue, fontname=Helvetica, fontsize=10, fixedsize=true, width=3.5];

  DynamicProgramming [label="Dynamic Programming:\nStores results of costly calculations"];
  Memoization [label="Memoization:\nCaches function results elegantly"];
  FunctionCall [label="Function Call:\nCalled with arguments"];
  CheckCache [label="Check Cache:\nAre arguments in cache?"];
  ReturnCache [label="Return Cached Result"];
  ComputeResult [label="Compute Result as normal"];
  UpdateCache [label="Update Cache with result"];
  SaveWork [label="Saves work for next calls"];

  CacheImpl [label="Cache Implementation:\nTable or Hash Table", shape=ellipse, fillcolor=lightgrey, width=3];

  DynamicProgramming -> Memoization;
  Memoization -> FunctionCall;
  FunctionCall -> CheckCache;
  CheckCache -> ReturnCache [label="Yes", fontsize=8];
  CheckCache -> ComputeResult [label="No", fontsize=8];
  ComputeResult -> UpdateCache;
  UpdateCache -> SaveWork;
  ReturnCache -> SaveWork;
  Memoization -> CacheImpl;

  label = "Memoization process flow\nDisclaimer: This diagram is generated with an AI model.";
  labelloc=top;
  fontsize=12;
}

digraph TCP_Connection_Release {
    rankdir=TB;
    node [shape=box, style=filled, fillcolor=lightblue, fontname="Arial"];

    TCP [label="TCP Connection Release"];
    Types [label="Types of Connection Release"];
    Graceful [label="Graceful Connection Release\n- Each TCP user releases its own data direction"];
    Abrupt [label="Abrupt Connection Release\n- One user closes both directions\n- Connection forced closed due to no reply or lack of resources"];

    RST_Mechanism [label="Abrupt Release Mechanism\n- Uses single segment with RST bit set"];

    Reasons [label="Reasons for Sending RST Segment"];
    Reason1 [label="Non-SYN segment received for non-existing connection (RFC 793)"];
    Reason2 [label="Segment received with invalid header (RFC 3360)\n- Causes connection close\n- Has led to security attacks (RFC 4953)"];
    Reason3 [label="Need to close existing connection\n(e.g., resource shortage or unreachable remote host)\n- Widespread usage observed"];

    TCP -> Types;
    Types -> Graceful;
    Types -> Abrupt;
    Abrupt -> RST_Mechanism;
    RST_Mechanism -> Reasons;
    Reasons -> Reason1;
    Reasons -> Reason2;
    Reasons -> Reason3;

    label = "TCP Connection Release Overview\nGenerated with an AI model";
    labelloc=top;
    fontsize=14;
}
